//! wasm-bindgen bindings of the GXR core (see docs/mobile.md).
//!
//! `version` stays here. Each area's exports live in its own module. Workers add exports in
//! their module and do not edit this file.
#![forbid(unsafe_code)]

mod camdata;
mod color;
mod export;
mod frame;
mod geometry;
mod hdr;
mod jpeg;
mod lut;
mod raw;
mod resample;

use wasm_bindgen::prelude::wasm_bindgen;

/// Core version, the same string `gxr-cli version` prints inside its JSON.
#[wasm_bindgen]
pub fn version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}
